import numpy as np

def relu(x):
    return np.maximum(0, x)

def relu_gradient(x):
    return np.where(x > 0, 1.0, 0.0)

def leaky_relu(x, alpha=0.01):
    return np.where(x > 0, x, alpha * x)

def leaky_relu_gradient(x, alpha=0.01):
    return np.where(x > 0, 1.0, alpha)

# The same "dying" neuron setup from the ReLU topic
dying_weight = -2.0
dying_bias = -5.0
test_inputs = np.array([0.5, 1.0, 2.0, 3.0])

print("Plain ReLU on the dying neuron:")
for x in test_inputs:
    pre_activation = dying_weight * x + dying_bias
    output = relu(pre_activation)
    gradient = relu_gradient(pre_activation)
    print(f"  input={x}: output={output:.3f}, gradient={gradient:.4f}")

print("\nLeaky ReLU on the same dying neuron:")
for x in test_inputs:
    pre_activation = dying_weight * x + dying_bias
    output = leaky_relu(pre_activation)
    gradient = leaky_relu_gradient(pre_activation)
    print(f"  input={x}: output={output:.3f}, gradient={gradient:.4f}")

print("\nNotice Leaky ReLU's gradient stays non-zero (0.01), leaving room for this neuron to still recover")
